          pt1: pTempManualRadial.pt1.clone(),
          pt2: pTempManualRadial.pt2.clone(),
          pt3: pTempManualRadial.pt3.clone(),
          center: pTempManualRadial.center.clone(),
          radius: pTempManualRadial.radius,
          offset2D: { dx: localMouseX - cx, dy: localMouseY - cy, initialZoom: activeZoom, initialH: slot.h },
