  if (resetDraft) window.__msClassDraft = null;
  if (!pData || !pData.parts || !pData.parts.length) { listEl.innerHTML = ''; const s0 = document.getElementById('msp-class-summary'); if (s0) s0.innerHTML = ''; return; }
  if (!window.__msClassDraft) {
    const src = (pData.classRules && typeof pData.classRules === 'object') ? pData.classRules : {};
    window.__msClassDraft = { tags: Object.assign({}, src.tags || {}), mats: Object.assign({}, src.mats || {}), parts: JSON.parse(JSON.stringify(src.parts || {})), cabs: JSON.parse(JSON.stringify(src.cabs || {})) }; // build410: + ручні правила деталей; build415: + правила корпусів
  }
  const draft = window.__msClassDraft;
  const q = (document.getElementById('msp-class-search') ? document.getElementById('msp-class-search').value : '').trim().toLowerCase();
  // збір тегів/матеріалів з лічильниками деталей + спірність (u) по чернетці
  const tags = {}, mats = {};
