    cnt.style.cssText = 'font-size:9px;color:#94a3b8;flex:0 0 auto;';
    row.appendChild(cnt);
    const cur = (kind === 'tag') ? (draft.tags[key] || 'auto') : (draft.mats[key] || 'auto');
    row.appendChild(mkSeg(kind, key, cur));
