  const matKeys = Object.keys(mats).sort((a, b) => (mats[b].u - mats[a].u) || (mats[b].n - mats[a].n));
  if (matKeys.length) addHeader('МАТЕРІАЛИ');
  matKeys.forEach(k => addRow('mat', k, mats[k], true));
