      const nm = document.createElement('span');
      nm.textContent = pr.label || pk;
      nm.title = (pr.label || pk) + ' — ручне правило';
      nm.style.cssText = 'font-size:10px;color:#334155;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
      row.appendChild(nm);
      const badge = document.createElement('span');
      badge.textContent = pr.cls === 'board' ? 'Доска' : 'Фурн.';
      badge.style.cssText = 'font-size:9px;padding:1px 6px;border-radius:3px;flex:0 0 auto;' + (pr.cls === 'board' ? 'background:#eaf3de;color:#3b6d11;' : 'background:#e6f1fb;color:#185fa5;');
      row.appendChild(badge);
      const del = document.createElement('button');
      del.textContent = '×';
