        if (pKeyLight) { pKeyLight.intensity = origLights.key.intensity; pKeyLight.color.setHex(origLights.key.color); if (origLights.key.pos) pKeyLight.position.copy(origLights.key.pos); }
        if (pFillLight) { pFillLight.intensity = origLights.fill.intensity; pFillLight.color.setHex(origLights.fill.color); if (origLights.fill.pos) pFillLight.position.copy(origLights.fill.pos); }
        if (pRimLight) { pRimLight.intensity = origLights.rim.intensity; pRimLight.color.setHex(origLights.rim.color); if (origLights.rim.pos) pRimLight.position.copy(origLights.rim.pos); }
