// build86: санітизація HTML із файлу проекту перед innerHTML (виноски/блоки опису).
// Файл .mspres.json портативний (можна отримати від колеги) — підроблене поле html
// («<img onerror=…>») виконало б довільний JS у діалозі з доступом до sketchup.*.
// Принцип той самий, що в onFetchUrlDataSuccess: чужий HTML вважаємо ворожим.
window.msSanitizeHtml = function (html) {
  const frag = document.createDocumentFragment();
  if (!html) return frag;
  let doc;
  try { doc = new DOMParser().parseFromString(String(html), 'text/html'); }
  catch (e) { return frag; }
  const BAD_TAGS = { SCRIPT: 1, IFRAME: 1, OBJECT: 1, EMBED: 1, LINK: 1, META: 1, BASE: 1, FORM: 1, SVG: 1, MATH: 1, TEMPLATE: 1 };
  const URL_ATTRS = { src: 1, href: 1, srcset: 1, action: 1, formaction: 1, poster: 1, background: 1, data: 1, 'xlink:href': 1 };
  const urlOk = (v) => /^\s*(data:image\/|https?:|mailto:|#|\.?\/)/i.test(String(v || ''));
  const walk = (node) => {
    const kids = Array.from(node.childNodes);
    for (const ch of kids) {
      if (ch.nodeType === 1) {
        if (BAD_TAGS[ch.tagName.toUpperCase()]) { ch.remove(); continue; }
        for (const a of Array.from(ch.attributes)) {
          const an = a.name.toLowerCase();
          if (an.indexOf('on') === 0) { ch.removeAttribute(a.name); continue; }
          if (URL_ATTRS[an] && !urlOk(a.value)) { ch.removeAttribute(a.name); continue; }
          if (an === 'style' && /url\s*\(/i.test(a.value)) { ch.removeAttribute(a.name); continue; }
        }
        walk(ch);
      } else if (ch.nodeType !== 3) {
        ch.remove(); // лишаємо лише елементи й текст (коментарі/CDATA геть)
      }
    }
  };
  walk(doc.body);
  Array.from(doc.body.childNodes).forEach(n => frag.appendChild(n));
  return frag;
};

// build323: назви деталей/фурнітури можуть містити HTML-ентіті («110&deg;») — вони показувались
// текстом як є (юзер-скрин: «110&deg;» замість «110°»). Декодуємо перед підстановкою в текст.
window.msDecodeEnt = function (s) {
  if (!s || String(s).indexOf('&') === -1) return s || '';
  const ta = document.createElement('textarea'); ta.innerHTML = String(s); return ta.value;
};
// build326: підпис деталі для виноски/лупи: декод ентіті + зріз службового префікса «__»/пробілів
// перед номером («__32. [ВМЗ] Дверцята» → «32. [ВМЗ] Дверцята») — юзер: «пробелы перед цифрами не пишем».
window.msCleanPartLabel = function (s) {
  // build269: зрізаємо і НУМЕРАЦІЮ ABF на початку («__100. …», «18. 6. …»), не лише підкреслення —
  // юзер: «везде надо префиксы убирать». Числа всередині назви («19мм») не чіпаємо (потрібна крапка+пробіл).
  return window.msDecodeEnt(s == null ? '' : String(s)).replace(/^[\s_]*(?:\d+\s*\.\s*)+/, '').replace(/^[\s_]+/, '');
};
// build326: чи прозорий (X-Ray) режим слота — та сама формула, що в депт-гейті build156.
// У НЕпрозорому режимі виноски чіпляються лише до ПЕРШОЇ (видимої) деталі під променем;
// у X-Ray — і до внутрішніх (полиці/ящики), як раніше.
function _pSlotXRayOn(slotIdx) {
  const s = (typeof pSlotSettings !== 'undefined') ? pSlotSettings[slotIdx] : null;
  return (s && s.xray) ? (s.xray === 'on') : !!pXRay;
}

// build86: «матеріалізатор» виноски — будує div+toolbar і вішає ВСІ обробники для
