  const _allPages = (typeof pages !== 'undefined' && Array.isArray(pages)) ? pages : null;
  const srcParts = (_allPages && _allPages[0] && _allPages[0].data && Array.isArray(_allPages[0].data.parts) && _allPages[0].data.parts.length)
    ? _allPages[0].data.parts : (Array.isArray(pData.parts) ? pData.parts : []);
