    const url = _pHwPartUrl(p);
    if (!url || boarded[url] || seen[url]) return;           // без ok_url / вже на дошці / дубль — пропуск
    seen[url] = true;
    // build568 (юзер: «чому картинок у таблиці нема, якщо вони вже завантажились?»): назва
