  if (!jobs.length) { alert('Уся фурнітура з посиланням уже додана (або в проєкті немає фурнітури з ok_url чи артикулом Вияр).'); return; }
  // build442: у чергу — ВСЮ незавантажену фурнітуру. Пагінація тепер ПІДСТОРІНКАМИ (по 36):
  // картки накопичуються в pData.hwBoard, _pHwSyncSubPages створює вкладки «Фурнітура 2/3…»,
  // а renderHwBoard показує зріз активної вкладки. Ліміту на лист більше немає.
  const _pg = pActivePageId;
  // build438: ЧЕРГА з обмеженою одночасністю (по 3) — раніше всі запити летіли разом і частина
  // відвалювалась по таймауту (18с), поки Ruby синхронно обробляв попередні.
  window.__hwFetchUrl = window.__hwFetchUrl || {};
  window.__hwFetchArt = window.__hwFetchArt || {}; // build568: артикул поряд з job — для зіставлення фото за art у таблиці «Кількість»
  window.__hwQueue = jobs.map(j => ({ url: j.url, art: j.art, pageId: _pg }));
  window.__hwActive = 0;
  window.__hwTotal = jobs.length;
