function renderHwBoard() {
  if (!pData) return;
  // build569: режим «Кількість» активний — картки ховаємо (дані pData.hwBoard лишаються цілі).
  if (pData.hwQtyEnabled) { const _b = document.getElementById('pres-hwboard'); if (_b) _b.remove(); return; }
  const legend = document.getElementById('pres-legend');
  const parent = legend ? legend.parentNode : document.getElementById('a4-sheet');
  let board = document.getElementById('pres-hwboard');
  const all = Array.isArray(pData.hwBoard) ? pData.hwBoard.filter(h => h.pageId === pActivePageId) : [];
  // build442: ПАГІНАЦІЯ ПІДСТОРІНКАМИ. Слайс 0 (перші 36) — на «3D Вид»; продовження — на
  // авто-підсторінках type:'hwboard'. Зріз визначаємо за активною підсторінкою.
  const HW_SLICE = 36;
  let sliceIdx = 0;
  const _pg = (typeof pages !== 'undefined' && Array.isArray(pages)) ? pages.find(p => p.id === (typeof activePageId !== 'undefined' ? activePageId : pActivePageId)) : null;
  if (_pg && _pg.state && typeof _pg.state.activeSubPageIndex === 'number' && _pg.state.activeSubPageIndex >= 0) {
    const subs = Array.isArray(_pg.state.subPages) ? _pg.state.subPages : [];
    const actSub = subs[_pg.state.activeSubPageIndex];
    if (actSub && actSub.type === 'hwboard') sliceIdx = subs.filter(s => s.type === 'hwboard').indexOf(actSub) + 1;
    else sliceIdx = -1; // активна НЕ hwboard підсторінка (bom/креслення) → дошку ховаємо
  }
  const items = (sliceIdx < 0) ? [] : all.slice(sliceIdx * HW_SLICE, sliceIdx * HW_SLICE + HW_SLICE);
  if (!items.length) { if (board) board.remove(); return; }
  if (!board) {
    board = document.createElement('div');
    board.id = 'pres-hwboard';
    // build437: ширина = майже весь лист → сітка розкладається ЗЛІВА-НАПРАВО (кілька колонок);
    // зсув top/left — щоб не лізло на верхній тулбар і рамку листа.
    // build439: minmax(100px,1fr) — auto-fill пакує СТІЛЬКИ колонок, скільки влазить (юзер: «справа
    // порожньо, ще влізе»), і розтягує їх на всю ширину (без порожньої смуги справа) → ~9 колонок.
    board.style.cssText = 'position:absolute; left:48px; top:54px; width:calc(100% - 96px); display:grid; grid-template-columns:repeat(auto-fill, minmax(100px, 1fr)); gap:8px; z-index:11; pointer-events:auto;';
    if (parent) parent.appendChild(board);
  }
  board.innerHTML = '';
  // build567 (юзер: «убери количество где фурнитура — или должно быть на каждой позиции, или
  // нигде» + «зачем дублировать список ещё раз?»): бейдж кількості (build563) показувався
  // лише коли назва картки ЗБІГАЛАСЬ з nazva у специфікації — для частини карток (назва з
  // фетчнутого заголовка сайту відрізняється) бейдж не з'являвся, і вигляд був непослідовним.
  // Прибрано звідси повністю — окрема друкована таблиця «Кількість фурнітури» (build564) вже
  // показує це НАДІЙНО для КОЖНОЇ позиції, дублювати тут більше не треба.
  items.forEach(h => {
    const card = document.createElement('div');
    card.style.cssText = 'border:1px solid #cbd5e1; border-radius:5px; padding:4px; background:#fff; box-sizing:border-box; text-align:center; position:relative;'; // build439: без фікс-ширини — заповнює клітинку сітки (1fr)
    if (h.image) {
      const img = document.createElement('img');
      img.src = h.image;
      img.style.cssText = 'width:100%; height:68px; object-fit:contain; display:block; margin:0 auto 3px auto;';
      img.addEventListener('load', () => { if (typeof pDirty !== 'undefined') pDirty = true; });
      card.appendChild(img);
    }
    const nm = document.createElement('div');
    nm.textContent = h.name || '';
    nm.contentEditable = 'true';
    nm.title = 'Клік — редагувати назву';
    nm.style.cssText = 'font-size:9px; line-height:1.25; word-break:break-word;';
    nm.addEventListener('mousedown', e => e.stopPropagation());
    nm.addEventListener('blur', () => { h.name = nm.innerText.trim(); pDirty = true; });
    card.appendChild(nm);
    const del = document.createElement('div');
    del.innerHTML = '✕';
    del.title = 'Прибрати';
    del.style.cssText = 'position:absolute; top:-6px; right:-6px; background:#e53e3e; color:#fff; border-radius:50%; width:16px; height:16px; font-size:11px; line-height:16px; text-align:center; cursor:pointer; opacity:0; transition:opacity 0.2s; z-index:10;';
    card.onmouseenter = () => del.style.opacity = '1';
    card.onmouseleave = () => del.style.opacity = '0';
    del.onclick = (e) => { e.stopPropagation(); pData.hwBoard = pData.hwBoard.filter(x => x.id !== h.id); renderHwBoard(); pDirty = true; };
    card.appendChild(del);
    board.appendChild(card);
  });
}
window.pAddProjectHardware = pAddProjectHardware;
window.renderHwBoard = renderHwBoard;

// build564 (юзер: «вместо всплывающего окна лучше пусть такая таблица будет на листах —
